select a.ID as userId,a.NAME as userName,b.ID as orgId,b.NAME as orgName,d.ID as roleId,d.NAME as roleName,d.CODE as roleCode from SYS_USER a left join SYS_ORG b on a.ORG_ID = b.ID left join SYS_RELATION c on a.ID = c.OBJECT_ID and c.CATEGORY = 'SYS_USER_HAS_ROLE' left join SYS_ROLE d on c.TARGET_ID = d.ID where a.DELETE_FLAG = 'NOT_DELETE' and a.USER_STATUS = 'ENABLE'
and ( a.ID in
#{item}
or a.ORG_ID in
#{item}
)
